content:
{
  "findings": [
    {
      "check_id": "CKV_GCP_60",
      "title": "Backup configuration is disabled for the Google SQL Database Instance",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "The backup configuration is disabled, which may result in data loss in case of an unexpected failure or deletion."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Google SQL Database Instance is not configured to require SSL",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "Not requiring SSL/TLS connections may expose data to interception and eavesdropping."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Log lock waits is disabled for the Google SQL Database Instance",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Disabling log lock waits may make it harder to diagnose performance issues related to lock contention."
    },
    {
      "check_id": "CKV_GCP_82",
      "title": "Google SQL Database Instance has deletion protection disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Disabling deletion protection may allow accidental deletion of the database instance."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = true\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}",
  "fix_summary": "Enabled backup configuration, required SSL/TLS connections, enabled log lock waits, and enabled deletion protection for the Google SQL Database Instance."
}
